with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('male sig', 'phrase', '01225c15-368f-55ae-b4a0-3287cfaac9af', 1, 'verb', null, 'to put on makeup', 'Hun maler sig altid før morgenmaden.', 'She always puts on makeup before breakfast.'), ('sprede sig', 'phrase', '130303f1-2deb-575e-922b-7143ed8883ae', 1, 'verb', null, 'to spread', 'Nyheden spredte sig hurtigt i byen.', 'The news spread quickly in the city.'), ('røre rundt', 'phrase', '43a7447f-f02f-5fc8-b13d-911af7491811', 1, 'verb', null, 'to stir', 'Hun rører rundt i gryden med en ske.', 'She stirs the pot with a spoon.'), ('ryste på hovedet', 'phrase', 'ef7769d8-034f-55fb-aa11-067a2f9b16d6', 1, 'verb', null, 'to shake one''s head (in denial)', 'Hun rystede på hovedet, da jeg spurgte hende.', 'She shook her head when I asked her.'), ('koncentrere sig om', 'phrase', '4b473d0d-f2d2-577d-ba33-95aede25b587', 1, 'verb', null, 'to concentrate on', 'Jeg koncentrerer mig om at læse bogen.', 'I concentrate on reading the book.'), ('skille sig af med', 'phrase', '8f992a43-4cfc-55f4-9542-bb8b166389e9', 1, 'verb', null, 'to get rid of', 'Hun vil gerne skille sig af med sin gamle sofa.', 'She wants to get rid of her old sofa.'), ('støde på', 'phrase', '9cee315a-3920-5b88-a253-59c941f74c47', 1, 'verb', null, 'to come across', 'Jeg stødte på en gammel ven i byen.', 'I ran into an old friend in town.'), ('tilbringe tid', 'phrase', '5179801c-287b-5ad9-8d7b-dfb6a383456c', 1, 'verb', null, 'to spend time', 'Vi tilbringer tid sammen hver weekend.', 'We spend time together every weekend.'), ('klæde sig af', 'phrase', 'db62190c-5de6-5c43-a101-b09ac137901c', 1, 'verb', null, 'to undress', 'Børnene klædte sig af og hoppede i poolen.', 'The children undressed and jumped into the pool.'), ('græde over', 'phrase', 'c61c9a54-e105-5b32-bfb4-09181cbeaf69', 1, 'verb', null, 'to cry over (sth.)', 'Hun græd over sin ødelagte telefon hele aftenen.', 'She cried over her broken phone all evening.'), ('brække sig', 'phrase', '61298f4a-d0d8-5a0a-9cba-2861eacc1ee1', 1, 'verb', null, 'to vomit, to throw up', 'Han spiste for meget og måtte brække sig bagefter.', 'He ate too much and had to vomit afterwards.'), ('føre dagbog', 'phrase', 'd259f90f-3b4f-5888-aaea-8b738727abac', 1, 'verb', null, 'to keep a diary', 'Hun fører dagbog hver aften.', 'She keeps a diary every evening.'), ('køle af', 'phrase', 'e6b0fef5-7ccc-5873-ac8b-563a2cee2353', 1, 'verb', null, 'to cool down (become colder)', 'Suppen skal køle af før vi spiser.', 'The soup must cool before we eat.'), ('køle af', 'phrase', '57e3e8f1-31a1-5374-8e80-45f10fc460eb', 2, 'verb', null, 'to cool down (calm down)', 'Han må køle af inden vi taler om det.', 'He needs to cool down before we talk about it.'), ('sværge på', 'phrase', 'dfaf898e-94a1-5d25-a328-e844c24c4c76', 1, 'verb', null, 'to swear to something', 'Han svor på at han talte sandt.', 'He swore that he was telling the truth.'), ('gud og hvermand', 'phrase', 'ee3af7be-e97e-5e6f-9dea-0ab3cb4532ae', 1, 'phrase', null, 'everyone and anyone', 'Gud og hvermand ved, at det er sandt.', 'Everyone and anyone knows that it is true.'), ('komme sig over', 'phrase', '053d28bb-05d1-5f1f-b49c-73aeb750b3ad', 1, 'verb', null, 'to recover (from illness, shock)', 'Hun har lige kommet sig over en slem forkølelse.', 'She has just recovered from a bad cold.'), ('komme op at', 'phrase', 'a6c828f5-9d65-5840-b2a4-faaa30d8fc0d', 1, 'verb', null, 'to get into a fight (with someone)', 'De kom op at skændes om penge.', 'They got into an argument about money.'), ('have tid til', 'phrase', '79f10fcc-f98e-5b79-b40b-7710cfafd1f6', 1, 'verb', null, 'to have time for', 'Jeg har tid til en kop kaffe inden mødet.', 'I have time for a cup of coffee before the meeting.'), ('tage tid', 'phrase', '1e1c1a45-4217-53ff-b808-4fec2befa744', 1, 'verb', null, 'to take time', 'Det tager tid at lære dansk.', 'It takes time to learn Danish.'), ('gå ind på', 'phrase', 'ba934f36-ce11-5305-ac9e-e5dc45f48693', 1, 'verb', null, 'to agree to (a proposal, plan)', 'Hun gik ind på at hjælpe os i weekenden.', 'She agreed to help us over the weekend.'), ('finde sammen', 'phrase', 'fcdbda2a-3c0e-5e47-ba82-b67c1929efec', 1, 'verb', null, 'to get together (as a couple)', 'De fandt sammen efter mange år som venner.', 'They got together after many years as friends.'), ('stå sammen', 'phrase', '9bb0cbe0-780d-59f0-a093-d5ef95ddd287', 1, 'verb', null, 'to stand together (support each other)', 'Vi står sammen, når det er svært.', 'We stand together when things are difficult.'), ('det er lige meget', 'phrase', 'f802c411-438f-5df0-b3c9-3077a076ef5f', 1, 'phrase', null, 'it doesn''t matter', 'Det er lige meget, hvad vi spiser i aften.', 'It doesn''t matter what we eat tonight.'), ('sætte sig for', 'phrase', '3aa0e9ba-35dd-5d8c-8929-eaf5d525ef5f', 1, 'verb', null, 'to decide (to do something)', 'Hun satte sig for at lære dansk på et år.', 'She set out to learn Danish in one year.'), ('sætte sig for at', 'phrase', 'b75c3f0b-1c03-5813-9370-1650db725d7b', 1, 'verb', null, 'to decide (to do something)', 'Hun satte sig for at lære dansk på et år.', 'She set out to learn Danish in one year.'), ('tale sammen', 'phrase', '5af2ef4c-e9c6-5e72-84ca-65b58f196ad0', 1, 'verb', null, 'to talk (to each other)', 'Vi taler sammen hver aften.', 'We talk to each other every evening.'), ('egne sig', 'phrase', 'ac461631-26e7-599c-ab30-0083f5dffca5', 1, 'verb', null, 'to be suitable', 'Den her bog egner sig godt til begyndere.', 'This book is well suited for beginners.'), ('finde vej', 'phrase', '1051440f-1be6-5383-a295-0ca7038eb9c0', 1, 'verb', null, 'to find the way', 'Hun fandt vej til stationen uden kort.', 'She found her way to the station without a map.'), ('bruge penge på', 'phrase', 'f310029d-0bcb-552f-8ca6-c3f08b709601', 1, 'verb', null, 'to spend money on', 'Jeg bruger penge på mad hver dag.', 'I spend money on food every day.'), ('lægge ud', 'phrase', '5f44c8ca-79f7-5614-879d-8ce08b635fef', 1, 'verb', null, 'to start (a story, explanation)', 'Hun lagde ud med at fortælle om sin ferie.', 'She started by telling about her vacation.'), ('lægge ud', 'phrase', '2c46f8f8-5d0c-5e08-8088-43c7b1396c14', 2, 'verb', null, 'to pay (for others, to be paid back)', 'Jeg lagde ud for billetterne til koncerten.', 'I paid for everyone''s concert tickets for now.'), ('høre op med at', 'phrase', '0c6ac8db-bddb-5f96-8086-8fc99f0ea561', 1, 'verb', null, 'to stop (doing something)', 'Jeg hører op med at ryge i morgen.', 'I''ll quit smoking tomorrow.'), ('slå på', 'phrase', '70343dec-3859-5823-b3c6-d0339c4479d9', 1, 'verb', null, 'to hit (something)', 'Han slog på bordet med knytnæven.', 'He hit the table with his fist.'), ('slå på', 'phrase', '3361d615-150b-5680-9f9f-03fad3a1a6c8', 2, 'verb', null, 'to emphasise (in speech)', 'Hun slår på, at det er vigtigt at møde til tiden.', 'She stresses that it is important to be on time.'), ('tænke efter', 'phrase', '4ba2c422-ff92-53d0-921f-0bb3f41b8333', 1, 'verb', null, 'to think carefully, to reflect', 'Du skal tænke efter før du svarer.', 'You need to think before you answer.'), ('synes om', 'phrase', '9c384956-cff2-5b2e-b7c2-8fa566546530', 1, 'verb', null, 'to like (have an opinion)', 'Jeg synes om den nye lærer.', 'I like the new teacher.'), ('gå rundt om', 'phrase', 'bc16c256-2a57-53c5-bd03-d79f1dcb107c', 1, 'verb', null, 'to walk around', 'Vi gik rundt om søen i aftes.', 'We walked around the lake yesterday evening.'), ('leve for', 'phrase', 'de8fde62-6d44-5755-af36-fbb122645ecf', 1, 'verb', null, 'to live for', 'Hun lever for sin musik.', 'She lives for her music.'), ('leve videre', 'phrase', 'a7e981a6-78b3-5607-b742-ca3dd9cdfb78', 1, 'verb', null, 'to continue living', 'Efter ulykken prøvede han bare at leve videre.', 'After the accident, he just tried to live on.'), ('sætte ord på', 'phrase', 'd2530c1c-3d19-5a8d-a17e-4620203b529d', 1, 'verb', null, 'to put into words', 'Hun sætter ord på sine følelser.', 'She puts her feelings into words.'), ('stå stille', 'phrase', '74d0397f-32d5-5002-9d8d-efe717fa978d', 1, 'verb', null, 'to stand still (not move)', 'Bilen stod stille i lang tid.', 'The car was stationary for a long time.'), ('stå stille', 'phrase', '5704ad0e-fee7-50de-8e95-ee2a0f3e4b03', 2, 'verb', null, 'to come to a standstill (about a process)', 'Arbejdet står stille på grund af regnen.', 'The work is at a standstill because of the rain.'), ('trække sig tilbage', 'phrase', 'efe681e3-ad3f-54db-bc6d-509c3ebf156f', 1, 'verb', null, 'to retreat, to withdraw', 'Soldaterne fik besked på at trække sig tilbage fra området.', 'The soldiers were told to withdraw from the area.'), ('trække ud', 'phrase', '4cc3bb01-1d1f-552c-a3fd-64f50103a000', 1, 'verb', null, 'to drag on (about time)', 'Mødet trak ud og varede over to timer.', 'The meeting dragged on and lasted over two hours.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0008' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
